78	/**
79	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
80	 * the family's control spec (compile-time constants); `action` is one of the three
81	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
82	 * a successful action (the same discipline as worker/game-update.ts).
83	 */
84	function powerScript(spec: GameControlSpec, action: string): string {
85	  const hints = spec.serviceHints.map(shq).join(" ");
86	  return [
87	    `unit=""`,
88	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
89	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
90	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
91	    `echo "NXGP:UNIT:$unit"`,
92	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
93	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
