108	  const href = `/dashboard/servers/${server.id}?tab=manage`;
109	
110	  if (SANDBOX) {
111	    await notify(
112	      server.userId,
113	      `Game service ${action} (sandbox) on ${server.hostname}`,
114	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
115	      href
116	    );
117	    return;
118	  }
119	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
120	
121	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
122	  if (action === "restart" && p.announce && spec.rcon === "source") {
123	    try {
124	      await withServerSsh(server as SftpServer, (conn) =>
125	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
126	      );
