208	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
209	    take: 100,
210	  });
211	  if (due.length === 0) return;
212	
213	  for (const s of due) {
214	    // Always advance the clock first so a server that is down / mid-operation does
215	    // not cause the same row to be reselected every tick.
216	    const nextRunAt = computeNextRun(s.hour, s.minute, now);
217	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
