import { db } from "../lib/db";
import { encryptSecret } from "../lib/crypto-box";
import { generateStrongPassword } from "../lib/ssh-exec";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
const execFileP = promisify(execFile);

async function main() {
  const serverId = "cmtd2ebgs12yahluy6d6vmcan";
  const node = "ns5002569";
  const vmid = 113;
  const password = generateStrongPassword(20);

  console.log("Setting new root password via QGA (pvesh)...");
  await execFileP("pvesh", [
    "create",
    `/nodes/${node}/qemu/${vmid}/agent/set-user-password`,
    "--username", "root",
    "--password", password,
  ]);
  console.log("QGA set-user-password call completed.");

  await db.server.update({
    where: { id: serverId },
    data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) },
  });
  console.log("DB rootPasswordEnc updated to match.");
  process.exit(0);
}
main().catch((e) => { console.error("FATAL", e); process.exit(1); });

