// `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
// keeps the vmid already persisted on the row.
const vmid = server.vmid ?? (await allocateFreshVmid(conn));

// The password must be generated ONCE per VM, not once per attempt. cloud-init's
// cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
// cipassword was baked into the FIRST boot's snippet and never re-applies on a
// later config change unless the guest gets a brand-new instance-id. A retried
// PROVISION (server.vmid already set = the clone below is skipped as
// `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
// again anyway and overwrite Server.rootPasswordEnc with a value the running VM
// never saw — every later SSH from the platform (control panel, GAME_POWER,
// mods, backups) then authenticated with a password that does not match
// /etc/shadow on the guest, failing with "All configured authentication methods
// failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
// logins ever, until the guest's password was force-resynced via the QGA
// set-user-password path). Reuse the already-stored password whenever this
// server already has a vmid (meaning some earlier attempt may have already
// cloned + booted it); only a truly first attempt mints a new one.
const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();

await handlers[job.type](job);
// Clear any error left over from an earlier failed attempt of THIS job. Without
// this, a job that failed once (error persisted, status QUEUED for retry) and
// then succeeded on a later attempt ends up DONE with a stale, misleading error
// still attached — indistinguishable from an actual silent failure to anyone
// reading Job.error (confirmed: a real PROVISION did exactly this today).
await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null } });
